   293	
   294	/**
   295	 * There are 2 possibilities that we can receive via pusher for a user's typing/leaving status:
   296	 * 1. The "new" way from New Expensify is passed as {[login]: Boolean} (e.g. {yuwen@expensify.com: true}), where the value
   297	 * is whether the user with that login is typing/leaving on the report or not.
   298	 * 2. The "old" way from e.com which is passed as {userLogin: login} (e.g. {userLogin: bstites@expensify.com})
   299	 *
   300	 * This method makes sure that no matter which we get, we return the "new" format
   301	 */
   302	function getNormalizedStatus(typingStatus: Pusher.UserIsTypingEvent | Pusher.UserIsLeavingRoomEvent): ReportUserIsTyping {
   303	    let normalizedStatus: ReportUserIsTyping;
   304	
   305	    if (typingStatus.userLogin) {
   306	        normalizedStatus = {[typingStatus.userLogin]: true};
   307	    } else {
   308	        normalizedStatus = typingStatus;
   309	    }
   310	
   311	    return normalizedStatus;
   312	}
