    23	function Authenticate(parameters: Parameters): Promise<Response> {
    24	    const commandName = 'Authenticate';
    25	
    26	    requireParameters(['partnerName', 'partnerPassword', 'partnerUserID', 'partnerUserSecret'], parameters, commandName);
    27	
    28	    return Network.post(commandName, {
    29	        // When authenticating for the first time, we pass useExpensifyLogin as true so we check
    30	        // for credentials for the expensify partnerID to let users Authenticate with their expensify user
    31	        // and password.
    32	        useExpensifyLogin: parameters.useExpensifyLogin,
    33	        partnerName: parameters.partnerName,
    34	        partnerPassword: parameters.partnerPassword,
    35	        partnerUserID: parameters.partnerUserID,
    36	        partnerUserSecret: parameters.partnerUserSecret,
    37	        twoFactorAuthCode: parameters.twoFactorAuthCode,
    38	        authToken: parameters.authToken,
    39	        shouldRetry: false,
    40	
    41	        // Force this request to be made because the network queue is paused when re-authentication is happening
    42	        forceNetworkRequest: true,
    43	
    44	        // Add email param so the first Authenticate request is logged on the server w/ this email
    45	        email: parameters.email,
    46	    });
    47	}
