    49	/**
    50	 * Reauthenticate using the stored credentials and redirect to the sign in page if unable to do so.
    51	 * @param [command] command name for logging purposes
    52	 */
    53	function reauthenticate(command = ''): Promise<void> {
    54	    // Prevent any more requests from being processed while authentication happens
    55	    NetworkStore.setIsAuthenticating(true);
    56	
    57	    const credentials = NetworkStore.getCredentials();
    58	    return Authenticate({
    59	        useExpensifyLogin: false,
    60	        partnerName: CONFIG.EXPENSIFY.PARTNER_NAME,
    61	        partnerPassword: CONFIG.EXPENSIFY.PARTNER_PASSWORD,
    62	        partnerUserID: credentials?.autoGeneratedLogin,
    63	        partnerUserSecret: credentials?.autoGeneratedPassword,
    64	    }).then((response) => {
    65	        if (response.jsonCode === CONST.JSON_CODE.UNABLE_TO_RETRY) {
    66	            // If authentication fails, then the network can be unpaused
    67	            NetworkStore.setIsAuthenticating(false);
    68	
    69	            // When a fetch() fails due to a network issue and an error is thrown we won't log the user out. Most likely they
    70	            // have a spotty connection and will need to try to reauthenticate when they come back online. We will error so it
    71	            // can be handled by callers of reauthenticate().
    72	            throw new Error('Unable to retry Authenticate request');
    73	        }
    74	
    75	        // If authentication fails and we are online then log the user out
    76	        if (response.jsonCode !== 200) {
    77	            const errorMessage = ErrorUtils.getAuthenticateErrorMessage(response);
    78	            NetworkStore.setIsAuthenticating(false);
    79	            Log.hmmm('Redirecting to Sign In because we failed to reauthenticate', {
    80	                command,
    81	                error: errorMessage,
    82	            });
    83	            redirectToSignIn(errorMessage);
    84	            return;
    85	        }
    86	
    87	        // Update authToken in Onyx and in our local variables so that API requests will use the new authToken
    88	        updateSessionAuthTokens(response.authToken, response.encryptedAuthToken);
    89	
    90	        // Note: It is important to manually set the authToken that is in the store here since any requests that are hooked into
    91	        // reauthenticate .then() will immediate post and use the local authToken. Onyx updates subscribers lately so it is not
    92	        // enough to do the updateSessionAuthTokens() call above.
    93	        NetworkStore.setAuthToken(response.authToken ?? null);
    94	
    95	        // The authentication process is finished so the network can be unpaused to continue processing requests
    96	        NetworkStore.setIsAuthenticating(false);
