     3	import React, {useContext, useEffect, useMemo, useRef} from 'react';
     4	import {useOnyx} from 'react-native-onyx';
     5	import HybridAppMiddleware from '@components/HybridAppMiddleware';
     6	import {ScrollOffsetContext} from '@components/ScrollOffsetContextProvider';
     7	import useActiveWorkspace from '@hooks/useActiveWorkspace';
     8	import useCurrentReportID from '@hooks/useCurrentReportID';
     9	import useTheme from '@hooks/useTheme';
    10	import useWindowDimensions from '@hooks/useWindowDimensions';
    11	import Firebase from '@libs/Firebase';
    12	import {FSPage} from '@libs/Fullstory';
    13	import hasCompletedGuidedSetupFlowSelector from '@libs/hasCompletedGuidedSetupFlowSelector';
    14	import Log from '@libs/Log';
    15	import {getPathFromURL} from '@libs/Url';
    16	import {updateLastVisitedPath} from '@userActions/App';
    17	import CONST from '@src/CONST';
    18	import ONYXKEYS from '@src/ONYXKEYS';
    19	import type {Route} from '@src/ROUTES';
    20	import ROUTES from '@src/ROUTES';
    21	import AppNavigator from './AppNavigator';
    22	import getPolicyIDFromState from './getPolicyIDFromState';
    23	import linkingConfig from './linkingConfig';
    24	import customGetPathFromState from './linkingConfig/customGetPathFromState';
    25	import getAdaptedStateFromPath from './linkingConfig/getAdaptedStateFromPath';
    26	import Navigation, {navigationRef} from './Navigation';
    27	import setupCustomAndroidBackHandler from './setupCustomAndroidBackHandler';
    28	import type {RootStackParamList} from './types';
    29	
    30	type NavigationRootProps = {
    31	    /** Whether the current user is logged in with an authToken */
    32	    authenticated: boolean;
    33	
    34	    /** Stores path of last visited page */
    35	    lastVisitedPath: Route;
    36	
    37	    /** Initial url */
    38	    initialUrl: string | null;
    39	
    40	    /** Fired when react-navigation is ready */
    41	    onReady: () => void;
    42	};
    43	
    44	/**
    45	 * Intercept navigation state changes and log it
    46	 */
    47	function parseAndLogRoute(state: NavigationState) {
    48	    if (!state) {
    49	        return;
    50	    }
    51	
    52	    const currentPath = customGetPathFromState(state, linkingConfig.config);
    53	
    54	    const focusedRoute = findFocusedRoute(state);
    55	
    56	    if (focusedRoute && !CONST.EXCLUDE_FROM_LAST_VISITED_PATH.includes(focusedRoute?.name)) {
    57	        updateLastVisitedPath(currentPath);
    58	    }
    59	
    60	    // Don't log the route transitions from OldDot because they contain authTokens
    61	    if (currentPath.includes('/transition')) {
    62	        Log.info('Navigating from transition link from OldDot using short lived authToken');
    63	    } else {
    64	        Log.info('Navigating to route', false, {path: currentPath});
    65	    }
    66	
    67	    Navigation.setIsNavigationReady();
    68	
    69	    // Fullstory Page navigation tracking
    70	    const focusedRouteName = focusedRoute?.name;
    71	    if (focusedRouteName) {
    72	        new FSPage(focusedRouteName, {path: currentPath}).start();
    73	    }
    74	}
    75	
    76	function NavigationRoot({authenticated, lastVisitedPath, initialUrl, onReady}: NavigationRootProps) {
    77	    const firstRenderRef = useRef(true);
    78	    const theme = useTheme();
    79	    const {cleanStaleScrollOffsets} = useContext(ScrollOffsetContext);
    80	
    81	    const currentReportIDValue = useCurrentReportID();
    82	    const {isSmallScreenWidth} = useWindowDimensions();
    83	    const {setActiveWorkspaceID} = useActiveWorkspace();
    84	    const [user] = useOnyx(ONYXKEYS.USER);
    85	
    86	    const [hasCompletedGuidedSetupFlow] = useOnyx(ONYXKEYS.NVP_ONBOARDING, {
    87	        selector: hasCompletedGuidedSetupFlowSelector,
    88	    });
    89	
    90	    const initialState = useMemo(() => {
    91	        if (!user || user.isFromPublicDomain) {
    92	            return;
    93	        }
    94	
    95	        // If the user haven't completed the flow, we want to always redirect them to the onboarding flow.
    96	        // We also make sure that the user is authenticated.
    97	        if (!hasCompletedGuidedSetupFlow && authenticated) {
    98	            const {adaptedState} = getAdaptedStateFromPath(ROUTES.ONBOARDING_ROOT.route, linkingConfig.config);
    99	            return adaptedState;
   100	        }
   101	
   102	        // If there is no lastVisitedPath, we can do early return. We won't modify the default behavior.
   103	        if (!lastVisitedPath) {
   104	            return undefined;
   105	        }
   106	
   107	        const path = initialUrl ? getPathFromURL(initialUrl) : null;
   108	
   109	        // If the user opens the root of app "/" it will be parsed to empty string "".
   110	        // If the path is defined and different that empty string we don't want to modify the default behavior.
   111	        if (path) {
   112	            return;
   113	        }
   114	
   115	        // Otherwise we want to redirect the user to the last visited path.
   116	        const {adaptedState} = getAdaptedStateFromPath(lastVisitedPath, linkingConfig.config);
   117	        return adaptedState;
   118	
   119	        // The initialState value is relevant only on the first render.
   120	        // eslint-disable-next-line react-compiler/react-compiler, react-hooks/exhaustive-deps
   121	    }, []);
   122	
   123	    // https://reactnavigation.org/docs/themes
   124	    const navigationTheme = useMemo(
   125	        () => ({
   126	            ...DefaultTheme,
   127	            colors: {
   128	                ...DefaultTheme.colors,
   129	                background: theme.appBG,
   130	            },
   131	        }),
   132	        [theme],
   133	    );
   134	
   135	    useEffect(() => {
   136	        if (firstRenderRef.current) {
   137	            setupCustomAndroidBackHandler();
   138	
   139	            // we don't want to make the report back button go back to LHN if the user
   140	            // started on the small screen so we don't set it on the first render
   141	            // making it only work on consecutive changes of the screen size
   142	            firstRenderRef.current = false;
   143	            return;
   144	        }
   145	
   146	        Navigation.setShouldPopAllStateOnUP(!isSmallScreenWidth);
   147	    }, [isSmallScreenWidth]);
   148	
   149	    const handleStateChange = (state: NavigationState | undefined) => {
   150	        if (!state) {
   151	            return;
   152	        }
   153	        const currentRoute = navigationRef.getCurrentRoute();
   154	        Firebase.log(`[NAVIGATION] screen: ${currentRoute?.name}, params: ${JSON.stringify(currentRoute?.params ?? {})}`);
   155	
   156	        const activeWorkspaceID = getPolicyIDFromState(state as NavigationState<RootStackParamList>);
   157	        // Performance optimization to avoid context consumers to delay first render
   158	        setTimeout(() => {
   159	            currentReportIDValue?.updateCurrentReportID(state);
   160	            setActiveWorkspaceID(activeWorkspaceID);
   161	        }, 0);
   162	        parseAndLogRoute(state);
   163	
   164	        // We want to clean saved scroll offsets for screens that aren't anymore in the state.
   165	        cleanStaleScrollOffsets(state);
   166	    };
   167	
   168	    return (
   169	        <NavigationContainer
   170	            initialState={initialState}
   171	            onStateChange={handleStateChange}
   172	            onReady={onReady}
   173	            theme={navigationTheme}
   174	            ref={navigationRef}
   175	            linking={linkingConfig}
   176	            documentTitle={{
   177	                enabled: false,
   178	            }}
   179	        >
   180	            {/* HybridAppMiddleware needs to have access to navigation ref and SplashScreenHidden context */}
   181	            <HybridAppMiddleware authenticated={authenticated}>
   182	                <AppNavigator authenticated={authenticated} />
   183	            </HybridAppMiddleware>
   184	        </NavigationContainer>
   185	    );
   186	}
   187	
   188	NavigationRoot.displayName = 'NavigationRoot';
   189	
   190	export default NavigationRoot;
   191
